// Data written to the writer is optionally gzipped, then optionally encrypted when encryptor is not nil.
func storageReadWriteCloser(count int, compress bool, encryptor *encryption.Encryptor) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()

		prs = append(prs, pr)

		var w io.Writer = pw
		var stageClosers []io.Closer

		if encryptor != nil {
			ew := encryptor.EncryptWriter(w)
			w = ew
			stageClosers = append(stageClosers, ew)
		}

		if compress {
			gw := gzip.NewWriter(w)
			w = gw
			stageClosers = append(stageClosers, gw)
		}

		pws = append(pws, w)

		// Closers must run from the outermost stage (gzip) to the innermost (encryption) so each stage flushes into the next,
		// and the pipe writer must be closed last to signal EOF to the reader.
		for j := len(stageClosers) - 1; j >= 0; j-- {
			pcs = append(pcs, stageClosers[j])
		}
		pcs = append(pcs, pw)
	}

	return prs, io.MultiWriter(pws...), config.NewMultiCloser(pcs)
}

